def pop_ready(self, now: float) -> tuple[str, str] | None:
        if not self.ready_heap or self.ready_heap[0][0] > now:
            return None
        _, host = heapq.heappop(self.ready_heap)
        q = self.back_queues[host]
        url = q.popleft()
        if not q:
            del self.back_queues[host]
        return host, url
